import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/%E9%98%B2%E5%AF%92%E3%82%B0%E3%83%83%E3%82%BA.html","title":"防寒グッズ","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":0.76,"words":227},"filePathRelative":"防寒グッズ.md"}`),a={name:`防寒グッズ.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="防寒グッズ" tabindex="-1"><a class="header-anchor" href="#防寒グッズ"><span>防寒グッズ</span></a></h1><p><a href="./グッズ関連.html">グッズ関連</a>から独立。</p><ul><li><a href="./レッグウォーマー.html">レッグウォーマー</a></li><li><a href="./着る毛布.html">着る毛布</a></li><li><a href="./充電式カイロ.html">充電式カイロ</a></li><li><a href="./電子レンジあんか.html">電子レンジあんか</a></li><li><a href="./ガスファンヒーター.html">ガスファンヒーター</a></li></ul><h2 id="_2025年-〜2026年-の奄美の防寒装備" tabindex="-1"><a class="header-anchor" href="#_2025年-〜2026年-の奄美の防寒装備"><span>2025年（〜2026年）の奄美の防寒装備</span></a></h2><p>鎌倉では住居が近代的だしガスファンヒーターなども完備なので室内は別段寒くないのだが、 奄美は使ってる宿が古い家屋なのでかえって奄美の方が防寒装備が問題になる、という逆転現象が起きている。</p><p>しかも帰る時には色々捨てるので、毎年新しく買うため色々試行錯誤する機会が多い。</p><h3 id="今年のテーマは機動力と疲れない防寒" tabindex="-1"><a class="header-anchor" href="#今年のテーマは機動力と疲れない防寒"><span>今年のテーマは機動力と疲れない防寒</span></a></h3><p>今年は<a href="./着る毛布.html">着る毛布</a>を導入して、疲れないというのが大切だなぁ、と思うようになった。 そこで機動力と疲れない防寒をテーマに色々考えている。</p><p>大体以下が主体。</p><ul><li>着る毛布</li><li>毛布っぽいズボン</li><li>足入れクッション</li><li>電子レンジあんか</li></ul><p>着る毛布が意外と良かったので、ズボンも履く毛布っぽい生地のものを試してみているが、結構いい。 やはりズボンは着脱が面倒という問題があるので着る毛布ほど良いものではないが、 軽さのおかげで2枚履いているのを忘れる程度には楽で、暖かさもまぁまぁ。</p><h3 id="足入れクッションと電子レンジあんか" tabindex="-1"><a class="header-anchor" href="#足入れクッションと電子レンジあんか"><span>足入れクッションと電子レンジあんか</span></a></h3><p>今年は足先の冷えの対策に足入れクッションを試してみている。これはルームシューズなどに比べると着脱が容易で、けれど暖かい、というメリットがある。 ただし移動時には使えない。</p><p>これまではもこもこ靴下を使っていたのだが、これは海に波チェックに行く時や買い物に行く時などには脱がないといけなくて、これがかったるいと思っていた。 そこですぐに外せる何かを求めて足入れクッションに行き着く。</p><p>全体的にはかなり満足している。</p><p>さらに、今年は<a href="./電子レンジあんか.html">電子レンジあんか</a>も導入して、これが足入れクッションと相性が良い。 すごく寒い日しか使わないけれど、すごく寒い日に足先が冷えるのはこれでだいぶ解決した。 さらにちょっとした時に<a href="./充電式カイロ.html">充電式カイロ</a>も併用できて良い。</p>`,16)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};